CREATE OR REPLACE FUNCTION public.sync_member_email() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.email IS DISTINCT FROM OLD.email THEN UPDATE public.profiles SET email=lower(NEW.email) WHERE user_id=NEW.id; UPDATE public.profile_status SET sponsor_id=(SELECT sponsor_id FROM public.sponsor_domains WHERE domain=lower(split_part(NEW.email,'@',2))), sponsor_tier=(SELECT tier FROM public.sponsor_domains WHERE domain=lower(split_part(NEW.email,'@',2))) WHERE user_id=NEW.id AND NOT manual_override; END IF; RETURN NEW; END $$;
CREATE TRIGGER phase2_confirmed_email AFTER UPDATE OF email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.sync_member_email();
COMMENT ON COLUMN public.profile_status.is_admin IS 'Display-only mirror; authorization uses public.user_roles exclusively.';